@import '~src/css/quasar.variables.scss', 'quasar/src/css/variables.sass';

$max-width: 1400px;
.live-container {
  background: linear-gradient(to bottom, #23263c, #190f25);
  img {
    width: 100%;
  }
  .banner-container {
    width: 100%;
    .promo-bg {
      background-size: cover;
      background-repeat: no-repeat;
      background-position: center center;
      height: 180px;
      margin: 10px;
      border-radius: 10px;
      img {
        width: 100%;
      }
    }
  }
}
.section-product {
  width: 95%;
  margin: 0 auto;
  max-width: $max-width;
  min-height: 50vh;
  /* position: relative; */
  .title {
    position: relative;
    &:after {
      content: "";
      position: absolute;
      height: 1px;
      width: 100%;
      left: 0;
      margin-top: 20px;
      background-color: rgb(214, 214, 214);
    }
  }
  .subintro {
    font-size: 16px;
    width: 100%;
    margin: auto;
    font-weight: 100;
    color: #190f25;
  }
  .item-group {
    width: 100%;
    margin: 0 auto;
    display: grid;
    grid-gap: 20px;
    grid-template-columns: repeat(2, 1fr);
  }
  .set {
    margin: auto;
    width: 100%;
    // &:nth-child(1) {
    //   grid-column-start: 2;
    //   grid-column-end: 3;
    // }
  }
  .items {
    position: relative;
    cursor: pointer;
    width: 100%;
    margin: auto;
    overflow: hidden;
    display: flex;
    align-items: flex-end;
    flex-direction: column;
    .bgimg {
      position: relative;

      .theme {
        overflow: hidden;
        img {
          width: 100%;
          vertical-align: middle;
          margin-top: 30px;
          &.logo {
            width: unset;
            height: 12%;
            position: absolute;
            left: 0;
            right: 0;
            bottom: 10%;
            margin: auto;
          }
        }
      }
      .main-object {
        position: absolute;
        bottom: 0;
        right: 0px;
        height: auto;
        overflow: hidden;
        transform: translateY(0px);
        transition: 0.3s;
        display: flex;
        align-items: flex-end;
        img {
          vertical-align: middle;
          // width: 100%;
          width: 75%;
        }
      }
    }
    &:hover .main-object {
      position: absolute;
      transform: translateX(-25px);
    }
    .sub-object {
      display: none;
      position: absolute;
      top: 0;
      left: 10px;
      height: 225px;
      overflow: hidden;
      transform: translateY(0px);
      transition: 0.3s;
      img {
        vertical-align: middle;
        width: 100%;
      }
    }
    .txt {
      padding: 10px 20px;
      background: linear-gradient(transparent, #2b2b4b);
      border-radius: 0 0 20px 20px;
      // position: absolute;
      // bottom: 0px;
      // // background: #2b2b4b;
      // padding: 20px;
      // color: #fff;
      // width: 100%;
      // filter: brightness(0.9);
      // border-radius: 0 0 20px 20px;

      p {
        font-size: 12px;
        font-weight: normal;
        font-stretch: normal;
        line-height: 16px;
      }
      img {
        max-width: 50%;
        margin: 0 0 10px;
        display: block;
        max-height: 30px;
      }
    }
    &:hover {
      .txt {
        opacity: 1;
        filter: brightness(1);
      }
    }
  }
}
